<script lang="ts">
 import {tick} from 'svelte';
 import {getDocument, GlobalWorkerOptions, type PDFDocumentProxy} from 'pdfjs-dist';
 import worker from 'pdfjs-dist/build/pdf.worker.min.mjs?url';
 import Pdf from './Pdf.svelte';
 import {loadGuideline,indexGuideline,readHash,writeHash,markReady,type Guideline,type HashState,type Doc} from '../../shared/data.js';
 let g=$state.raw<Guideline|null>(null), state=$state.raw<HashState>(readHash());
 let pdf=$state.raw<Promise<PDFDocumentProxy>|null>(null), selected=$state(''), zoom=$state(false), search=$state(''), rendered=$state(0);
 $effect(()=>{const hash=()=>{state=readHash();zoom=false;};addEventListener('hashchange',hash);GlobalWorkerOptions.workerSrc=worker;void loadGuideline().then(data=>{g=data;pdf=getDocument({url:data.pdf}).promise;});return()=>removeEventListener('hashchange',hash);});
 const ix=$derived(g?indexGuideline(g):null);
 const pages=$derived(g?[...new Set(g.documents.map(d=>d.page))].sort((a,b)=>a-b):[]);
 const question=$derived(g&&state.view==='trace'?g.questions.find(q=>q.id===state.question):null);
 const ruleDoc=$derived(state.view==='rule'?ix?.docs.get(state.document):null);
 const sentence=$derived(state.view==='rule'?ix?.sentence(`${state.document}:${state.sentence}`):null);
 const parsed=$derived(state.view==='rule'?ix?.rules.get(`${state.document}:${state.sentence}`):null);
 const matches=$derived(g&&state.view==='explore'?g.documents.filter(d=>(d.source+' '+d.id+' '+d.sentences.map(s=>s.ace).join(' ')).toLowerCase().includes(state.query.toLowerCase())):[]);
 const activeDocs=$derived(new Set(question?.documents??(ruleDoc?[ruleDoc.id]:state.view==='explore'?matches.map(d=>d.id):[])));
 const current=$derived(ix?.docs.get(selected)||ruleDoc|| (question?ix?.docs.get(question.statements[0]?.document):null)||matches[0]||null);
 const notFound=$derived(state.view==='trace'&&!question||state.view==='rule'&&!sentence);
 const activePages=$derived(new Set(g?.documents.filter(d=>activeDocs.has(d.id)).map(d=>d.page)??[]));
 function go(next:HashState){selected='';zoom=false;state=next;writeHash(next);}
 function open(d:Doc){selected=d.id;zoom=true;}
 function coords(page:number){const i=pages.indexOf(page);return {x:(i%7)*100+50,y:Math.floor(i/7)*153+62};}
 const connections=$derived.by(()=>{
  if(!g)return [];
  if(question)return question.statements.slice(1).map((s,i)=>({a:ix!.docs.get(question.statements[i].document)!.page,b:ix!.docs.get(s.document)!.page,label:'Answer citation order'})).filter(e=>e.a!==e.b);
  const reps=pages.map(p=>g!.documents.find(d=>d.page===p)!); const result:{a:number;b:number;label:string}[]=[];
  const terms=new Map(reps.map(d=>[d.id,new Set<string>()]));
  for(const c of g.concepts)for(const mention of c.mentions){const id=mention.slice(0,mention.lastIndexOf(':'));terms.get(id)?.add(c.label);}
  for(let i=0;i<reps.length;i++){let best:{j:number;labels:string[]}|null=null;for(let j=i+1;j<reps.length;j++){const labels=[...terms.get(reps[i].id)!].filter(c=>terms.get(reps[j].id)!.has(c));if(labels.length>(best?.labels.length??0))best={j,labels};}if(best&&best.labels.length>1)result.push({a:reps[i].page,b:reps[best.j].page,label:best.labels.join(', ')});}
  return result;
 });
 $effect(()=>{if(g&&rendered>=pages.length){void state;void tick().then(markReady);}});
</script>
<main>
 <header><div><p class="brand">CNL / CKC • Source atlas</p><h1>The guideline is the map.</h1><p>Follow the knowledge back to the page that says it.</p></div><a href="#overview" onclick={(e)=>{e.preventDefault();go({view:'overview'});}}>All pages</a></header>
 {#if g&&ix&&pdf}
 <nav aria-label="Atlas views"><label>Trace an answer<select value={state.view==='trace'?state.question:''} onchange={e=>e.currentTarget.value&&go({view:'trace',question:e.currentTarget.value})}><option value="">Choose a question</option>{#each g.questions as q}<option value={q.id}>{q.question}</option>{/each}</select></label><form onsubmit={e=>{e.preventDefault();go({view:'explore',query:search});}}><label>Explore the knowledge base<input bind:value={search} placeholder="Find naloxone, taper, pain…" /></label><button>Find passages</button></form></nav>
 <p class="legend">Nodes are document markers docked below their PDF page. Solid threads join shared concepts; amber threads follow answer citations. Positions within a dock are not passage coordinates.</p>
 <div class="workspace">
 <section class="atlas" aria-label="Guideline page map"><div class="sheet">
 <svg class:trace={!!question} viewBox={`0 0 700 ${Math.ceil(pages.length/7)*153}`} preserveAspectRatio="none" aria-label="Page relationships">{#each connections as edge}{@const a=coords(edge.a)}{@const b=coords(edge.b)}<path d={`M ${a.x} ${a.y} Q ${(a.x+b.x)/2+40} ${(a.y+b.y)/2} ${b.x} ${b.y}`}><title>{edge.label}</title></path>{/each}</svg>
 {#each pages as page}<div class="folio" class:lit={activePages.has(page)}><button class="page" aria-label={`Read page ${page}`} onclick={()=>open(g!.documents.find(d=>d.page===page)!)}><Pdf {pdf} {page} done={()=>rendered++}/><span>Page {page}</span></button><div class="dock">{#each g.documents.filter(d=>d.page===page) as d}<button class:active={activeDocs.has(d.id)} class:rec={d.kind==='recommendation'} title={d.id} aria-label={`Open ${d.id}`} onclick={()=>open(d)}></button>{/each}</div></div>{/each}
 </div><p>{g.documents.length} documents across {pages.length} source pages. A square marker identifies a recommendation; a round marker identifies another document.</p></section>
 <aside aria-label="Reading desk"><h2>{state.view==='overview'?'Reading desk':state.view==='trace'?'Answer trail':state.view==='rule'?'One rule, in context':'Matching passages'}</h2>
 {#if notFound}<p role="alert">This question or sentence was not found. Choose a question or a document marker.</p>{/if}
 {#if question}<h3>{question.question}</h3><p class="notice">{g.derivation}</p><ol>{#each question.statements as s}<li><button class="textlink" onclick={()=>{selected=s.document;go({view:'rule',document:s.document,sentence:s.sentence});}}>{ix.sentence(`${s.document}:${s.sentence}`)?.ace}</button><small>{s.document} / sentence {s.sentence} / page {ix.docs.get(s.document)?.page}</small></li>{/each}</ol>{/if}
 {#if state.view==='explore'}<p>{matches.length} documents contain “{state.query}”.</p><div class="results">{#each matches as d}<button class="result" onclick={()=>open(d)}>{d.id}<small>Page {d.page}: {d.source}</small></button>{/each}</div>{/if}
 {#if sentence}<h3>{ruleDoc?.id}, sentence {sentence.n}</h3><p class="sentence">{sentence.ace}</p><h4>{parsed?'Clinical rule parse':'Text reading (heuristic, not a clinical parse)'}</h4><dl><dt>Condition</dt><dd>{parsed?.condition??sentence.condition??'No explicit condition in this record.'}</dd><dt>Mode</dt><dd>{parsed?.mode??sentence.modal}{sentence.negated?' / negative action':''}</dd><dt>Conclusion</dt><dd>{parsed?parsed.subject+' '+parsed.actions.map(a=>(a.polarity==='negative'?'not ':'')+a.verb+' '+a.object+' '+a.modifiers.map(m=>m.preposition+' '+m.value).join(' ')).join('; '):sentence.conclusion}</dd></dl>{/if}
 {#if current}<section class="passage"><h3>{current.id}</h3><p>Source page {current.page}. {current.section}</p><blockquote>{current.source}</blockquote><button onclick={()=>zoom=!zoom}>{zoom?'Close full page':'Read full PDF page'}</button>{#if zoom}<section class="fullpage" aria-label={`Enlarged source page ${current.page}`}><button onclick={()=>zoom=false}>Close enlarged page {current.page}</button><p>{current.source}</p>{#key current.page}<Pdf {pdf} page={current.page} large/>{/key}</section>{/if}<details><summary>Read every encoded sentence</summary>{#each current.sentences as s}<p><a href={`#rule=${current.id}:${s.n}`} onclick={(e)=>{e.preventDefault();go({view:'rule',document:current.id,sentence:s.n});}}>Sentence {s.n}</a> {s.ace}</p>{/each}</details></section>{:else if state.view==='overview'}<p>Select a page or a document marker to open its source. The sheet preserves the guideline’s page order, rather than inventing a clinical layout.</p><h3>The clinical spine</h3>{#each g.recommendations as r}<button class="spine" onclick={()=>{const d=ix.docs.get(r.id);if(d)open(d);}}>Recommendation {r.number}<small>Page {r.page}; {r.implementation.length} implementation documents</small></button>{/each}{/if}
 </aside></div>
 <section class="register"><details><summary>Scope exclusions ({g.exclusions.length} records)</summary><p>The recommendations do not apply under these conditions. Absence of an exclusion does not establish that a patient belongs to the guideline population.</p>{#each g.exclusions as e}<p><a href={`#rule=${e.document}:${e.sentence}`}>{e.document}, sentence {e.sentence}</a>: {e.ace}</p>{/each}</details><details><summary>Superseded statements ({g.supersessions.length})</summary>{#each g.supersessions as s}<p><s>{s.ace}</s><br/>{s.document}, sentence {s.sentence}. Superseded {String(s.date).replace(/(\d{4})(\d{2})(\d{2})/,'$1-$2-$3')} by <a href={s.url}>{s.citation}</a>.</p>{/each}</details><details><summary>Relationships as text ({connections.length})</summary>{#each connections as e}<p>Page {e.a} to page {e.b}: {e.label}</p>{/each}</details></section>
 {:else}<p>Opening the guideline PDF…</p>{/if}
</main>
<style>
 main{max-width:1600px;margin:auto;padding:26px 32px}header{display:flex;align-items:center;justify-content:space-between;gap:20px}h1{font-size:36px;line-height:1.12;margin:5px 0 10px;font-weight:650}h2{font-size:24px;margin:0 0 14px}h3{font-size:18px}p{margin:8px 0 14px}.brand{font-weight:700;color:var(--action)}a,.textlink{color:var(--action)}nav{display:flex;gap:24px;padding:20px 0;align-items:end}label{display:flex;flex-direction:column;gap:5px;font-weight:650}select,input,button{color:var(--text);background:var(--surface-raised);border:1px solid var(--border);padding:9px;max-width:100%}select{width:460px}form{display:flex;gap:8px;align-items:end;flex:1}input{width:260px}button,a,summary{cursor:pointer}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--focus-ring);outline-offset:3px}.legend{color:var(--text-muted);font-size:13px;max-width:1000px}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:28px}.atlas{background:#263b48;padding:18px;color:white;min-width:0}.atlas>p{font-size:13px;margin-bottom:0}.sheet{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:15px 12px;position:relative}.folio{min-width:0;position:relative}.page{padding:0;border:0;display:block;width:100%;position:relative}.page span{position:absolute;bottom:0;left:0;right:0;background:#fff;color:#171b21;font-size:11px;line-height:18px}.dock{display:flex;flex-wrap:wrap;gap:2px;min-height:14px;padding-top:4px}.dock button{padding:0;width:5px;height:5px;background:#c5d1d9;border:0;border-radius:50%}.dock button.rec{border-radius:0;width:8px;height:8px;background:#fff}.dock button.active{background:#ffb45d;outline:1px solid #fff}.lit .page{outline:3px solid #ffb45d}.sheet svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:2}.sheet path{fill:none;stroke:#b6c4cd;stroke-width:1.1;opacity:.4}.sheet svg.trace path{stroke:#ffb45d;stroke-width:3;opacity:.95}aside{min-width:0;max-height:1000px;overflow:auto;padding-right:6px}blockquote{font-family:var(--font-prose);font-size:15px;line-height:1.75;margin:14px 0;padding-left:12px;border-left:4px solid var(--action)}small{display:block;font-size:12px;color:var(--text-muted)}.spine,.result{display:block;width:100%;text-align:left;margin:8px 0}.result small{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.results{max-height:350px;overflow:auto}.textlink{background:none;border:0;text-align:left;padding:0}li{margin-bottom:18px}ol{padding-left:22px}.notice{padding:10px;background:var(--surface-sunken);font-size:13px}.sentence{font-family:var(--font-prose)}dt{font-weight:700}dd{margin:2px 0 12px}details{margin:16px 0}summary{font-weight:650}details p{max-width:75ch;overflow-wrap:anywhere}.register{padding-top:24px}aside :global(canvas){margin-top:16px}.passage{margin-top:24px}button{white-space:normal}a,small,h3{overflow-wrap:anywhere}
 .fullpage{position:fixed;z-index:5;inset:24px;max-width:1000px;margin:auto;padding:20px;background:var(--surface-raised);border:2px solid var(--border);overflow:auto;box-shadow:0 0 0 100vmax #0008}.fullpage>button{position:sticky;top:0;z-index:1}.fullpage>p{max-width:75ch}
 @media(max-width:1000px){main{padding:20px}.workspace{grid-template-columns:minmax(0,1fr) 300px}.sheet{grid-template-columns:repeat(4,minmax(0,1fr))}.sheet svg{display:none}nav{flex-wrap:wrap}select{width:100%}}
 @media(max-width:650px){main{padding:16px}header{align-items:start}header>a{white-space:nowrap}h1{font-size:28px}nav,form{display:block}nav>label,form label{margin-bottom:10px}input,select{width:100%}.workspace{display:flex;flex-direction:column}aside{order:-1;max-height:490px;background:var(--surface-raised);padding:16px;border:1px solid var(--border)}.sheet{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.atlas{padding:16px}.dock button{width:8px;height:8px}.sheet svg{display:none}.legend{font-size:12px}}
 @media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style>
